using System;using System.IO;using System.Collections.Generic;
// Real NPC dialogs AND the town quest log carry word1 at offset6. It is a
// completion context, not an NPC id or proof of standing in an NPC room.
// The service uses saved objectives, inventory and the quest's target NPC.
class Offline70QuestFinishRequestFG {internal ushort QuestId,Selection,Context;}
class Offline70QuestWireFG {
 static byte[] Request(byte[] encrypted,byte[] keys,ushort op,int size){byte[] b=Offline70FlowCipherFG.Crypt(encrypted,keys,op%14,false);if(b.Length!=size||BitConverter.ToUInt16(b,0)!=op||BitConverter.ToUInt16(b,2)==0)throw new InvalidDataException("Quest request bounds/marker");return b;}
 internal static ushort ParseAccept(byte[] encrypted,byte[] keys){byte[] b=Request(encrypted,keys,33,16);for(int i=4;i<b.Length;i++)if(b[i]!=0)throw new InvalidDataException("Quest accept padding");return BitConverter.ToUInt16(b,2);}
 internal static ushort ParseAbandon(byte[] encrypted,byte[] keys){byte[] b=Request(encrypted,keys,34,8);for(int i=4;i<b.Length;i++)if(b[i]!=0)throw new InvalidDataException("Quest abandon padding");return BitConverter.ToUInt16(b,2);}
 internal static byte[] AbandonReply(ushort id,bool success,byte[] keys){return EncryptPacket(1,34,success?new byte[]{1,(byte)id,(byte)(id>>8)}:new byte[]{0,0x13},keys);}
 internal static ushort ParseProgress(byte[] encrypted,byte[] keys){byte[] b=Request(encrypted,keys,35,8);for(int i=4;i<b.Length;i++)if(b[i]!=0)throw new InvalidDataException("Quest progress selector/padding");return BitConverter.ToUInt16(b,2);}
 internal static Offline70QuestFinishRequestFG ParseFinish(byte[] encrypted,byte[] keys){byte[] b=Request(encrypted,keys,36,16);for(int i=8;i<b.Length;i++)if(b[i]!=0)throw new InvalidDataException("Quest finish padding");return new Offline70QuestFinishRequestFG{QuestId=BitConverter.ToUInt16(b,2),Selection=BitConverter.ToUInt16(b,4),Context=BitConverter.ToUInt16(b,6)};}
 static byte[] EncryptPacket(byte type,ushort op,byte[] plain,byte[] keys){int block=op%14==8?16:8;byte[] pad=new byte[(plain.Length+block-1)/block*block];plain.CopyTo(pad,0);return Offline70RoleProtocol.Packet(type,op,Offline70FlowCipherFG.Crypt(pad,keys,op%14,true));}
 internal static byte[] AcceptReply(ushort id,uint progress,bool success,byte[] keys){return EncryptPacket(1,33,success?Offline70QuestCatalogFG.AcceptBody(id,progress):new byte[]{0,0x12},keys);}
 internal static byte[] AcceptItemsBody(ushort id,uint progress,Offline70EconomyState before,Offline70EconomyState after){List<Offline70EconomyEntry> received=new List<Offline70EconomyEntry>();foreach(Offline70EconomyEntry current in after.Inventory){if(current.List!=0)continue;Offline70EconomyEntry old=Offline70Economy.Find(before,current.List,current.Slot);if(old==null||old.ItemId!=current.ItemId||current.Quantity>old.Quantity)received.Add(current);}if(received.Count>255)throw new InvalidDataException("Quest start row count");using(MemoryStream m=new MemoryStream())using(BinaryWriter w=new BinaryWriter(m)){w.Write((byte)1);w.Write(id);w.Write(progress);w.Write((byte)received.Count);foreach(Offline70EconomyEntry e in received){w.Write(e.Slot);w.Write(e.ItemId);Offline70EconomyEntry old=Offline70Economy.Find(before,e.List,e.Slot);w.Write(e.Quantity-(old!=null&&old.ItemId==e.ItemId?old.Quantity:0));}return m.ToArray();}}
 internal static byte[] AcceptItemsReply(ushort id,uint progress,Offline70EconomyState before,Offline70EconomyState after,byte[] keys){return EncryptPacket(1,33,AcceptItemsBody(id,progress,before,after),keys);}
 internal static byte[] ProgressReply(ushort id,uint progress,bool success,byte[] keys){return EncryptPacket(1,35,success?Offline70QuestCatalogFG.ProgressBody(id,progress):new byte[]{0,0x16},keys);}
 internal static byte[] FinishReply(ushort id,bool success,byte[] keys){return EncryptPacket(1,36,success?Offline70QuestCatalogFG.FinishBody(id):new byte[]{0,0x16},keys);}
 // Native C14800 subtracts consumed rows (7 bytes), then ADDS reward rows
 // (15 bytes). A stack already present must receive only the committed gain.
 internal static byte[] FinishRewardBody(ushort id,uint gold,Offline70EconomyState before,Offline70EconomyState after){
  List<Offline70EconomyEntry> consumed=new List<Offline70EconomyEntry>(),received=new List<Offline70EconomyEntry>();
  foreach(Offline70EconomyEntry old in before.Inventory){if(old.List!=0)continue;Offline70EconomyEntry current=Offline70Economy.Find(after,old.List,old.Slot);if(current==null||current.ItemId!=old.ItemId||current.Quantity<old.Quantity)consumed.Add(old);}
  foreach(Offline70EconomyEntry current in after.Inventory){if(current.List!=0)continue;Offline70EconomyEntry old=Offline70Economy.Find(before,current.List,current.Slot);if(old==null||old.ItemId!=current.ItemId||current.Quantity>old.Quantity)received.Add(current);}
  if(consumed.Count>255||received.Count>255)throw new InvalidDataException("Quest reward row count");
  using(MemoryStream m=new MemoryStream())using(BinaryWriter w=new BinaryWriter(m)){w.Write((byte)1);w.Write(id);w.Write((byte)0);w.Write(gold);w.Write((byte)consumed.Count);foreach(Offline70EconomyEntry old in consumed){Offline70EconomyEntry current=Offline70Economy.Find(after,old.List,old.Slot);w.Write(old.List);w.Write(old.Slot);w.Write(current!=null&&current.ItemId==old.ItemId?old.Quantity-current.Quantity:old.Quantity);}w.Write((byte)0);w.Write((byte)received.Count);foreach(Offline70EconomyEntry current in received){Offline70EconomyEntry old=Offline70Economy.Find(before,current.List,current.Slot);uint prior=old!=null&&old.ItemId==current.ItemId?old.Quantity:0;w.Write(current.Slot);w.Write(current.ItemId);w.Write(current.Quantity-prior);w.Write((byte)0);w.Write((ushort)0);w.Write(current.Durability);}return m.ToArray();}
 }
 internal static byte[] FinishRewardReply(ushort id,uint gold,Offline70EconomyState before,Offline70EconomyState after,byte[] keys){return EncryptPacket(1,36,FinishRewardBody(id,gold,before,after),keys);}
 internal static byte[] OfferReply(byte level,ushort[] ids,byte[] keys){return EncryptPacket(0,21,Offline70QuestCatalogFG.OfferBody(level,ids),keys);}
 internal static byte[] HistoryBody(IList<ushort> completed){int maximum=0;foreach(ushort id in completed){if(id==0)throw new InvalidDataException("Current70 completed quest bounds");if(id>7764)continue;maximum=Math.Max(maximum,id);}byte[] body=new byte[5+maximum];BitConverter.GetBytes((uint)(maximum+1)).CopyTo(body,0);foreach(ushort id in completed)if(id<=7764)body[4+id]=1;return body;}
 internal static byte[] HistoryReply(IList<ushort> completed,byte[] keys){byte[] plain=HistoryBody(completed),pad=new byte[(plain.Length+15)&~15];plain.CopyTo(pad,0);return Offline70RoleProtocol.Packet(0,365,ProbeLoginCandidate.Crypt(pad,keys,true));}
}
class QuestWireFixturesFG {
 static void Save(string folder,string label,byte[] b){using(FileStream f=new FileStream(Path.Combine(folder,label),FileMode.CreateNew,FileAccess.Write))f.Write(b,0,b.Length);}
 static void Eq(byte[] a,byte[] b){if(a.Length!=b.Length)throw new InvalidDataException("Wire fixture length");for(int i=0;i<a.Length;i++)if(a[i]!=b[i])throw new InvalidDataException("Wire fixture mismatch");}
 static int Main(string[] args){if(args.Length!=1)return 2;if(Directory.Exists(args[0]))throw new IOException("Fresh wire fixture directory required");Directory.CreateDirectory(args[0]);byte[] keys=new byte[334];for(int i=0;i<keys.Length;i++)keys[i]=(byte)i;
  Eq(Offline70QuestWireFG.FinishReply(101,true,keys),Offline70QuestFinish.Reply(keys,true));Eq(Offline70QuestWireFG.FinishReply(101,false,keys),Offline70QuestFinish.Reply(keys,false));Offline70QuestFinishRequestFG captured=Offline70QuestWireFG.ParseFinish(Offline70QuestFinish.RequestEncrypted(),keys);if(captured.QuestId!=101||captured.Context!=1||captured.Selection!=ushort.MaxValue)throw new InvalidDataException("Captured quest101 finish regression");
  foreach(ushort id in new ushort[]{101,102,103,1146,7764}){Save(args[0],"accept-"+id+".plain.bin",Offline70QuestCatalogFG.AcceptBody(id,id==103?10u:1u));Save(args[0],"accept-"+id+".packet.bin",Offline70QuestWireFG.AcceptReply(id,id==103?10u:1u,true,keys));Save(args[0],"progress-"+id+".plain.bin",Offline70QuestCatalogFG.ProgressBody(id,0));Save(args[0],"progress-"+id+".packet.bin",Offline70QuestWireFG.ProgressReply(id,0,true,keys));Save(args[0],"finish-"+id+".plain.bin",Offline70QuestCatalogFG.FinishBody(id));Save(args[0],"finish-"+id+".packet.bin",Offline70QuestWireFG.FinishReply(id,true,keys));
   byte[] a=new byte[16],p=new byte[8],f=new byte[16];BitConverter.GetBytes((ushort)33).CopyTo(a,0);BitConverter.GetBytes((ushort)35).CopyTo(p,0);BitConverter.GetBytes((ushort)36).CopyTo(f,0);foreach(byte[] b in new byte[][]{a,p,f})BitConverter.GetBytes(id).CopyTo(b,2);BitConverter.GetBytes(id==103?(ushort)0:ushort.MaxValue).CopyTo(f,4);BitConverter.GetBytes((ushort)1).CopyTo(f,6);byte[] ea=Offline70FlowCipherFG.Crypt(a,keys,5,true),ep=Offline70FlowCipherFG.Crypt(p,keys,7,true),ef=Offline70FlowCipherFG.Crypt(f,keys,8,true);if(Offline70QuestWireFG.ParseAccept(ea,keys)!=id||Offline70QuestWireFG.ParseProgress(ep,keys)!=id||Offline70QuestWireFG.ParseFinish(ef,keys).QuestId!=id)throw new InvalidDataException("Generic quest request parse");Save(args[0],"finish-"+id+".request-plain.bin",f);Save(args[0],"finish-"+id+".request-encrypted.bin",ef);
   foreach(int op in new int[]{33,35,36}){byte[] b=(byte[])(op==33?a:op==35?p:f).Clone();b[b.Length-1]=1;bool bad=false;try{byte[] e=Offline70FlowCipherFG.Crypt(b,keys,op%14,true);if(op==33)Offline70QuestWireFG.ParseAccept(e,keys);else if(op==35)Offline70QuestWireFG.ParseProgress(e,keys);else Offline70QuestWireFG.ParseFinish(e,keys);}catch(InvalidDataException){bad=true;}if(!bad)throw new InvalidDataException("Padding accepted");}}
  foreach(byte level in new byte[]{1,2,70}){ushort[] ids=level==1?new ushort[]{102}:new ushort[]{102,103,1146};Save(args[0],"offers-"+level+".plain.bin",Offline70QuestCatalogFG.OfferBody(level,ids));Save(args[0],"offers-"+level+".packet.bin",Offline70QuestWireFG.OfferReply(level,ids,keys));Save(args[0],"stats-"+level+".bin",Offline70SwordmanGrowthFG.Stats(0,level));}
  Save(args[0],"progress-103-remaining9.plain.bin",Offline70QuestCatalogFG.ProgressBody(103,9));Save(args[0],"progress-103-remaining9.packet.bin",Offline70QuestWireFG.ProgressReply(103,9,true,keys));
  Save(args[0],"history.plain.bin",Offline70QuestWireFG.HistoryBody(new ushort[]{101,102,103,1146,7764}));Save(args[0],"history.packet.bin",Offline70QuestWireFG.HistoryReply(new ushort[]{101,102,103,1146,7764},keys));Console.WriteLine("PASS generic quest33/35/36 requests/replies, fixed101 byte regression, three offer levels, completed history");return 0;
 }
}
